// 2D value-gradient (Perlin-style) noise with a seeded permutation table.
// No external noise packages — implemented from scratch.

/** Small, fast, seedable PRNG returning floats in [0, 1). */
export function mulberry32(seed) {
  let a = seed >>> 0;
  return function () {
    a |= 0;
    a = (a + 0x6d2b79f5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

/**
 * Build a doubled permutation table (512 entries) from a numeric seed.
 * Deterministic for a given seed.
 */
export function createPermutation(seed) {
  const rand = mulberry32(seed);
  const p = new Uint8Array(256);
  for (let i = 0; i < 256; i++) p[i] = i;

  // Fisher–Yates shuffle driven by the seeded PRNG.
  for (let i = 255; i > 0; i--) {
    const j = Math.floor(rand() * (i + 1));
    const tmp = p[i];
    p[i] = p[j];
    p[j] = tmp;
  }

  const perm = new Uint8Array(512);
  for (let i = 0; i < 512; i++) perm[i] = p[i & 255];
  return perm;
}

// Eight unit gradient directions.
const GRAD_X = [1, -1, 1, -1, 1, -1, 0, 0];
const GRAD_Y = [1, 1, -1, -1, 0, 0, 1, -1];

function fade(t) {
  // Smoothstep-style ease curve: 3t^2 - 2t^3
  return t * t * (3 - 2 * t);
}

function grad(hash, x, y) {
  const h = hash & 7;
  return GRAD_X[h] * x + GRAD_Y[h] * y;
}

/**
 * Create a noise2(x, y) function bound to a specific seed.
 * Output is in [-1, 1].
 */
export function createNoise2(seed) {
  const perm = createPermutation(seed);

  return function noise2(x, y) {
    const xi = Math.floor(x);
    const yi = Math.floor(y);
    const xf = x - xi;
    const yf = y - yi;

    const x0 = xi & 255;
    const y0 = yi & 255;
    const x1 = (x0 + 1) & 255;
    const y1 = (y0 + 1) & 255;

    const u = fade(xf);
    const v = fade(yf);

    const aa = perm[perm[x0] + y0];
    const ab = perm[perm[x0] + y1];
    const ba = perm[perm[x1] + y0];
    const bb = perm[perm[x1] + y1];

    const n00 = grad(aa, xf, yf);
    const n01 = grad(ab, xf, yf - 1);
    const n10 = grad(ba, xf - 1, yf);
    const n11 = grad(bb, xf - 1, yf - 1);

    const nx0 = n00 + u * (n10 - n00);
    const nx1 = n01 + u * (n11 - n01);
    const value = nx0 + v * (nx1 - nx0);

    // Gradient dot products are bounded by sqrt(2); normalize to [-1, 1].
    return Math.max(-1, Math.min(1, value / Math.SQRT2));
  };
}

// --- Default-seeded instance so `noise2` can be used directly ---

const DEFAULT_SEED = 1337;
let activePermSeed = DEFAULT_SEED;
let activeNoise = createNoise2(activePermSeed);

/** Re-seed the module-level `noise2` function. Deterministic per seed. */
export function setSeed(seed) {
  if (seed !== activePermSeed) {
    activePermSeed = seed >>> 0 || DEFAULT_SEED;
    activeNoise = createNoise2(activePermSeed);
  }
}

/**
 * Sample 2D gradient noise at (x, y).
 * Uses the current seed (see setSeed); output is in [-1, 1].
 */
export function noise2(x, y) {
  return activeNoise(x, y);
}

