import * as THREE from 'three';
import { createNoise2 } from './noise.js';

/**
 * Build a low-poly terrain mesh for a splash page.
 *
 * @param {object} [options]
 * @param {number} options.seed     - Seed driving the noise permutation table.
 * @param {number} [options.size=64]   - World-space width/height of the terrain.
 * @param {number} [options.cells=32]  - Grid subdivisions per side.
 * @param {number} [options.amplitude=6] - Max vertical displacement (fbm output in [-1,1] scaled by this).
 * @returns {THREE.Mesh} Flat-lying plane with displaced vertices and computed normals.
 */
export function buildTerrain({ seed, size = 64, cells = 32, amplitude = 6 } = {}) {
  const geometry = new THREE.PlaneGeometry(size, size, cells, cells);
  geometry.rotateX(-Math.PI / 2); // lie flat: plane now spans X/Z, height along Y

  const noise = createNoise2(seed);

  // Fractal Brownian motion: 4 octaves, lacunarity 2, gain 0.5.
  const positions = geometry.attributes.position;
  const baseFrequency = cells / size; // one noise unit per cell
  let octaveFrequency = 1;
  let octaveAmplitude = 1;
  let maxAmplitude = 0;

  const offsets = [];
  for (let o = 0; o < 4; o++) {
    offsets.push({
      fx: octaveFrequency * baseFrequency,
      ox: o * 17.31 + 0.7,
      oy: o * 9.13 + 3.1,
      amp: octaveAmplitude,
    });
    maxAmplitude += octaveAmplitude;
    octaveFrequency *= 2;
    octaveAmplitude *= 0.5;
  }

  for (let i = 0; i < positions.count; i++) {
    const x = positions.getX(i);
    const z = positions.getZ(i);

    let h = 0;
    for (let o = 0; o < offsets.length; o++) {
      const { fx, ox, oy, amp } = offsets[o];
      h += amp * noise(x * fx + ox, z * fx + oy);
    }

    // Normalize by total octave amplitude so |h| <= 1 before scaling.
    positions.setY(i, (h / maxAmplitude) * amplitude);
  }

  geometry.computeVertexNormals();

  return new THREE.Mesh(
    geometry,
    new THREE.MeshStandardMaterial({ color: 0x6fae5c, flatShading: true })
  );
}

