import { describe, it, expect } from 'vitest';
import { setSeed, noise2 } from '../src/noise.js';
import { buildTerrain } from '../src/terrain.js';

describe('noise2', () => {
  it('is deterministic per seed', () => {
    for (const seed of [1, 42, 9999]) {
      setSeed(seed);
      const first = [];
      for (let x = 0; x < 10; x++) {
        for (let y = 0; y < 10; y++) {
          first.push(noise2(x * 0.37 + 0.11, y * 0.53 - 0.29));
        }
      }

      // Re-seed with the same seed and sample again.
      setSeed(seed);
      let i = 0;
      for (let x = 0; x < 10; x++) {
        for (let y = 0; y < 10; y++) {
          expect(noise2(x * 0.37 + 0.11, y * 0.53 - 0.29)).toBe(first[i++]);
        }
      }
    }
  });

  it('stays bounded in [-1, 1] over a 50x50 sample sweep', () => {
    for (const seed of [7, 1234]) {
      setSeed(seed);
      for (let i = 0; i < 50; i++) {
        for (let j = 0; j < 50; j++) {
          const v = noise2(i * 0.173 - 12.5, j * 0.231 - 8.75);
          expect(v).toBeGreaterThanOrEqual(-1);
          expect(v).toBeLessThanOrEqual(1);
        }
      }
    }
  });
});

describe('buildTerrain', () => {
  const params = { seed: 2024, size: 64, cells: 32, amplitude: 6 };

  it('keeps every vertex y within [-amplitude, amplitude]', () => {
    const mesh = buildTerrain(params);
    const positions = mesh.geometry.attributes.position;
    for (let i = 0; i < positions.count; i++) {
      const y = positions.getY(i);
      expect(y).toBeGreaterThanOrEqual(-params.amplitude);
      expect(y).toBeLessThanOrEqual(params.amplitude);
    }
  });

  it('produces identical position buffers for the same seed', () => {
    const a = buildTerrain(params).geometry.attributes.position.array;
    const b = buildTerrain({ ...params }).geometry.attributes.position.array;
    expect(a.length).toBe(b.length);
    expect(Array.from(a)).toEqual(Array.from(b));
  });

  it('has a normal attribute with unit-length normals (within 1e-4)', () => {
    const mesh = buildTerrain(params);
    const normals = mesh.geometry.attributes.normal;
    expect(normals).toBeDefined();
    expect(mesh.geometry.attributes.position.count).toBe(
      normals.count
    );

    for (let i = 0; i < normals.count; i++) {
      const nx = normals.getX(i);
      const ny = normals.getY(i);
      const nz = normals.getZ(i);
      const len = Math.sqrt(nx * nx + ny * ny + nz * nz);
      expect(Math.abs(len - 1)).toBeLessThanOrEqual(1e-4);
    }
  });
});

